}

.download-panel strong { font-size: 14px; }
.download-panel p { margin: 3px 0 0; color: var(--muted); font-size: 13px; }

.reproduction-button {
  flex: 0 0 auto;
  border-color: var(--primary);
  border-radius: 5px;
  background: #fff;
  color: var(--primary);
  font-weight: 650;
}

.reproduction-button:hover,
.reproduction-button:focus {
  border-color: var(--primary-dark);
  background: var(--primary-light);
  color: var(--primary-dark);
}

@media (max-width: 1050px) {
  .app-shell { grid-template-columns: 290px minmax(0, 1fr); }
  .chart-grid { grid-template-columns: 1fr; }
}

@media (max-width: 760px) {
  .app-header { padding: 15px 18px; }
  .app-header h1 { font-size: 21px; }
  .study-info { width: calc(100% - 28px); margin-top: 16px; }
  .app-shell { display: block; padding: 16px 14px 30px; }
  .filter-panel { position: static; margin-bottom: 16px; }
  .results-heading { align-items: flex-start; flex-direction: column; }
  .result-counts { justify-content: flex-start; }
  .chart-grid { gap: 16px; }
  .chart-card { padding-inline: 10px; }
  .quartile-label { min-height: 48px; }
  .quartile-value { font-size: 25px; }
  .download-panel { align-items: flex-start; flex-direction: column; }
  .reproduction-button { width: 100%; }
}
